// Convierte los eventos del calendario en la forma que espera la web.
// Solo se conservan hora, título y lugar: nada de invitados ni descripciones.

const zona = 'America/Santiago';

const fmt = (iso, soloFecha) => {
  if (soloFecha) return 'Todo el día';
  return new Date(iso).toLocaleTimeString('es-CL', {
    hour: '2-digit', minute: '2-digit', timeZone: zona,
  });
};

const agenda = [];

for (const item of $input.all()) {
  const e = item.json;
  if (!e || !e.start) continue;
  if (e.status === 'cancelled') continue;

  const esDiaCompleto = Boolean(e.start.date);
  const inicio = e.start.dateTime || e.start.date;
  const fin = e.end?.dateTime || e.end?.date;

  agenda.push({
    hora: esDiaCompleto
      ? 'Todo el día'
      : `${fmt(inicio)} – ${fmt(fin)}`,
    titulo: e.summary || 'Sin título',
    lugar: e.location || '',
    tipo: 'clinica',
  });
}

// Fecha de hoy en formato YYYY-MM-DD, hora de Chile.
const fecha = new Date().toLocaleDateString('en-CA', { timeZone: zona });

return [{ json: { fecha, agenda } }];

// Junta todo lo recogido y arma el mensaje para Claude.

const base = $('Limpiar agenda').first().json;
const resumen = $('Detalle de los papers').first().json;

// --- Papers ---
const papers = [];
const r = resumen?.result || {};
for (const uid of (r.uids || [])) {
  const p = r[uid];
  if (!p) continue;
  const doi = (p.articleids || []).find((a) => a.idtype === 'doi')?.value;
  papers.push({
    titulo: p.title || '',
    revista: p.fulljournalname || p.source || '',
    fecha: p.pubdate || '',
    doi: doi ? `https://doi.org/${doi}` : `https://pubmed.ncbi.nlm.nih.gov/${uid}/`,
  });
}

// --- Noticias: los 8 titulares más recientes ---
const titulares = $input.all().slice(0, 8).map((i) => ({
  titulo: i.json.title || '',
  detalle: (i.json.contentSnippet || i.json.content || '').slice(0, 400),
  url: i.json.link || '',
  fuente: 'Emol',
}));

// --- Ciclo de turnos: 4 días que rotan desde el 3 de agosto de 2026 ---
const turnos = [
  { ciclo: 'Día 1 · Turno largo', detalle: '08:00–20:00 · Sin consultas' },
  { ciclo: 'Día 2 · Turno noche', detalle: '20:00–08:00 · Consultas 09:00–17:00' },
  { ciclo: 'Día 3 · Libre saliente', detalle: 'Consultas 15:00–19:00' },
  { ciclo: 'Día 4 · Segundo libre', detalle: 'Consultas 09:00–19:00' },
];
const ancla = new Date('2026-08-03T12:00:00-04:00');
const hoy = new Date(`${base.fecha}T12:00:00-04:00`);
const dias = Math.floor((hoy - ancla) / 86400000);
const turno = turnos[((dias % 4) + 4) % 4];

const prompt = `Eres el asistente de Franco, kinesiólogo especialista en kinesiología respiratoria y maxilofacial, dueño de la clínica rehabilita.me en Iquique y Alto Hospicio (Chile). Prepara su brief de hoy.

PAPERS RECIENTES DE PUBMED:
${JSON.stringify(papers, null, 2)}

TITULARES DE HOY:
${JSON.stringify(titulares, null, 2)}

SU AGENDA DE HOY:
${JSON.stringify(base.agenda, null, 2)}

Devuelve SOLO un objeto JSON, sin texto alrededor y sin bloques de código markdown, con esta forma exacta:

{
  "ideas": [
    { "hook": "frase gancho en primera persona o segunda persona, entre comillas angulares", "formato": "Reel 30 s | Carrusel 6 slides", "idea": "qué grabar o mostrar, 2 frases concretas", "base": "de qué paper o tema sale" }
  ],
  "papers": [
    { "titulo": "título traducido al español, claro", "revista": "nombre de la revista", "resumen": "2-3 frases con el hallazgo y el tamaño muestral si aparece", "aplicacion": "1 frase: qué hacer con esto en su práctica", "doi": "la URL del DOI tal cual venía" }
  ],
  "noticias": [
    { "categoria": "Economía · Chile | Salud | IA · Mercados | Norte grande", "titulo": "titular reescrito con tus palabras", "detalle": "2 frases de contexto", "fuente": "nombre del medio", "url": "enlace original" }
  ]
}

Reglas:
- 4 ideas de contenido. Al menos 2 deben salir de los papers de hoy. Una puede ser sobre la atención a domicilio, que es su diferenciador.
- Máximo 4 papers, los más aplicables a su especialidad. Conserva los DOI exactos.
- Máximo 4 noticias, priorizando economía chilena, salud, tecnología/IA y la Región de Tarapacá. Reescribe los titulares con tus propias palabras, nunca los copies literalmente.
- Escribe en español de Chile, claro y directo, sin jerga innecesaria.`;

return [{
  json: {
    fecha: base.fecha,
    ciclo: turno.ciclo,
    ciclo_detalle: turno.detalle,
    agenda: base.agenda,
    prompt,
  },
}];

// Toma la respuesta de Claude y la deja lista para guardar.

const contexto = $('Armar el contexto').first().json;
const respuesta = $input.first().json;

let texto = (respuesta.content || [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('\n')
  .trim();

// Por si el modelo devolvió el JSON envuelto en un bloque de código.
texto = texto.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

let datos;
try {
  datos = JSON.parse(texto);
} catch (e) {
  throw new Error('Claude no devolvió JSON válido. Respuesta recibida: ' + texto.slice(0, 300));
}

return [{
  json: {
    fecha: contexto.fecha,
    ciclo: contexto.ciclo,
    ciclo_detalle: contexto.ciclo_detalle,
    agenda: contexto.agenda,
    ideas: datos.ideas || [],
    papers: datos.papers || [],
    noticias: datos.noticias || [],
  },
}];
